function translateMarkup(html){if(language!=='en')return html;return Object.entries(english).sort((a,b)=>b[0].length-a[0].length).reduce((s,[ar,en])=>s.split(ar).join(en),html).replaceAll('ج.م','EGP').replaceAll('جنيه','EGP')}
function arabicPeriod(value){if(language==='ar')return value;return {'This month':'هذا الشهر','Today':'اليوم','Last 7 days':'آخر 7 أيام','Last month':'الشهر الماضي','This year':'هذا العام'}[value]||value}
function svgIcon(name){const p={overview:'<rect x="3" y="3" width="7" height="8" rx="1"/><rect x="14" y="3" width="7" height="5" rx="1"/><rect x="14" y="12" width="7" height="9" rx="1"/><rect x="3" y="15" width="7" height="6" rx="1"/>',building:'<path d="M4 21V5l8-3 8 3v16M2 21h20M8 8h1m6 0h1M8 12h1m6 0h1M10 21v-5h4v5"/>',panel:'<path d="m3 8 18-3-2 12-18 2zM5 13l15-2M10 7l-1 12m7-13-1 12M8 22h10"/>',battery:'<rect x="3" y="7" width="17" height="12" rx="2"/><path d="M20 11h2v4h-2M11 9l-2 4h3l-1 4 4-6h-3l1-2"/>',weather:'<path d="M7 18a5 5 0 0 1-.5-10A7 7 0 0 1 20 10a4 4 0 0 1-.5 8H7zM7 2v2m-5 5h2m12-5-1 2"/>',report:'<path d="M6 2h9l5 5v15H6zM14 2v6h6M9 13h8m-8 4h8"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a8 8 0 0 1-1.6.9l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.6-.9l-1.7.7-1.4-2.4 1.4-1.1a7 7 0 0 1 0-1.9l-1.4-1.1 1.4-2.4 1.7.7a8 8 0 0 1 1.6-.9l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.6.9l1.7-.7 1.4 2.4-1.4 1.1a7 7 0 0 1 0 1.8z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',leaf:'<path d="M20 4c-8 0-14 3-14 10a6 6 0 0 0 6 6c7 0 10-7 8-16zM4 21c2-5 6-8 12-12"/>',coins:'<ellipse cx="12" cy="6" rx="8" ry="3"/><path d="M4 6v5c0 2 4 3 8 3m8-8v4M4 11v5c0 2 4 3 8 3m8-9v5c0 2-4 3-8 3"/>',grid:'<path d="M3 3h8v8H3zM13 3h8v5h-8zM13 10h8v11h-8zM3 13h8v8H3z"/>',arrow:'<path d="M4 17 10 11l4 4 6-8M15 7h5v5"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${p[name]||p.overview}</svg>`}
function setLanguage(next){language=next;localStorage.setItem('solar_lang',language);document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';document.body.classList.toggle('english',language==='en');applyShellLanguage();render()}
function setTheme(next){theme=next;localStorage.setItem('solar_theme',theme);render()}
function setPalette(next){palette=next;localStorage.setItem('solar_palette',palette);render();toast(language==='ar'?'تم تطبيق السمة':'Theme applied')}
function applyShellLanguage(){
  document.querySelector('#langToggle').textContent=language==='ar'?'EN':'AR';
  document.querySelector('#langToggle').onclick=()=>setLanguage(language==='ar'?'en':'ar');
  document.querySelector('#themeToggle').innerHTML=`<span aria-hidden="true">${theme==='light'?'☾':'☀'}</span>`;
  document.querySelector('#themeToggle').title=language==='ar'?(theme==='light'?'التبديل إلى الداكن':'التبديل إلى الفاتح'):(theme==='light'?'Switch to dark theme':'Switch to light theme');
  document.querySelector('#themeToggle').setAttribute('aria-label',document.querySelector('#themeToggle').title);
  document.querySelector('#themeToggle').onclick=()=>setTheme(theme==='light'?'dark':'light');
  document.querySelector('#homeLink').textContent=language==='ar'?'الرئيسية':'Home';
  document.querySelector('#systemStatus').textContent=language==='ar'?'النظام يعمل':'System online';
  document.querySelector('#roleLabel').textContent=language==='ar'?'مشرف النظام':'System Administrator';
  document.querySelector('#footerCaption').textContent=language==='ar'?'لوحة متابعة الطاقة الشمسية':'Campus solar energy dashboard';
  document.querySelector('.nav-label').textContent=language==='ar'?'القائمة الرئيسية':'MAIN MENU';
  const links=[['dashboard','overview','الرئيسية','Home'],['buildings','building','المباني','Buildings'],['panels','panel','الألواح الشمسية','Solar Panels'],['batteries','battery','البطاريات','Batteries'],['weather','weather','الطقس والتوقعات','Weather & Forecast'],['reports','report','التقارير','Reports']];
  document.querySelector('.nav-links').innerHTML=links.map(([key,ico,ar,en])=>`<a href="#${key}" data-page="${key}" class="nav-link ${location.hash==='#'+key||(!location.hash&&key==='dashboard')?'active':''}"><span class="nav-icon">${svgIcon(ico)}</span>${language==='ar'?ar:en}</a>`).join('');
  const settingsLink=document.querySelector('.sidebar-bottom > a');
  settingsLink.innerHTML=`<span class="nav-icon">${svgIcon('settings')}</span>${language==='ar'?'الإعدادات':'Settings'}`;
}
const fmt=n=>new Intl.NumberFormat('en-US').format(Math.round(n||0));
const money=n=>'ج.م '+fmt(n);
const pct=(a,b)=>b?Math.round(a/b*100):0;
const iconFor=i=>svgIcon(['building','building','building','building','building','building','building'][i%7]);
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">إدارة الطاقة المستدامة</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function periodSelect(){const choices=["هذا الشهر","اليوم","آخر 7 أيام","الشهر الماضي"];return `<select class="select" id="periodSelect">${choices.map(x=>`<option ${db.period===x?"selected":""}>${x}</option>`).join("")}</select>`}
function btnAdd(label,kind){return `<button class="btn btn-primary" data-action="add-${kind}"><span>＋</span>${label}</button>`}
function render(){
  const page=(location.hash.slice(1)||'dashboard'),key=pages[page]?page:'dashboard';
  applyShellLanguage();document.querySelectorAll('.nav-link[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===key));
  document.querySelector('#pageCrumb').textContent=language==='en'?translateMarkup(pages[key]):pages[key];
  document.querySelector('#pageContent').innerHTML=translateMarkup(views[key]());
  if(key==='weather'){const w=document.querySelector('#weatherCondition');if(w)w.outerHTML=`<label class="forecast-input">${language==='ar'?'عدد الألواح للتجربة':'Panel count to estimate'}<input id="forecastPanelCount" type="number" min="1" value="10"></label>`;}
  document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';document.body.classList.toggle('english',language==='en');document.body.classList.toggle('dark-theme',theme==='dark');document.body.dataset.palette=palette;
  decorateIcons(key);bindCommon();if(key==='dashboard')drawDashboard();if(key==='reports')drawReport();if(key==='weather')updateWeather();
  document.title=language==='ar'?'Solar System | إدارة الطاقة':'Solar System | Campus Energy';
}
function decorateIcons(page){const set={dashboard:['sun','grid','coins','leaf'],buildings:['building','grid','sun','arrow'],panels:['panel','sun','arrow','grid'],batteries:['battery','sun','arrow','grid'],weather:['sun','weather','panel','coins'],reports:['grid','sun','arrow','leaf'],settings:['settings','coins','grid','leaf']}[page]||[];document.querySelectorAll('.kpi-icon').forEach((el,i)=>{if(set[i])el.innerHTML=svgIcon(set[i])});document.querySelectorAll('.battery-icon').forEach(el=>el.innerHTML=svgIcon('battery'))}
function paletteSettingsMarkup(){
  const options=language==='ar'?[{id:'current',name:'السمة الحالية',note:'الأخضر الداكن كما هو الآن',light:['#f5f8f5','#ffffff','#0b3b30'],dark:['#050809','#11191b','#c8ff57']},{id:'mono',name:'أبيض وأسود',note:'تباين واضح وبسيط',light:['#f1f2f2','#ffffff','#17191a'],dark:['#050607','#17191a','#f8f9f9']},{id:'warm',name:'أبيض دافئ وفحمي',note:'خلفية دافئة مع فحمي',light:['#f5f1e9','#fffefa','#806342'],dark:['#080706','#1a1815','#f0d4a9']},{id:'ice',name:'أبيض جليدي وأسود',note:'خلفية باردة ولمسة سماوية',light:['#edf4f7','#ffffff','#28758d'],dark:['#05090c','#151b1f','#b7edfa']},{id:'mint',name:'أبيض مائل للنعناعي',note:'خلفية خضراء خفيفة وفحمي',light:['#edf4ef','#ffffff','#35845a'],dark:['#050907','#151a17','#b5f2c9']}]:[{id:'current',name:'Current theme',note:'Keep the existing dark green look',light:['#f5f8f5','#ffffff','#0b3b30'],dark:['#050809','#11191b','#c8ff57']},{id:'mono',name:'Black & White',note:'Clean, high contrast',light:['#f1f2f2','#ffffff','#17191a'],dark:['#050607','#17191a','#f8f9f9']},{id:'warm',name:'Warm White & Charcoal',note:'Warm white surfaces and charcoal',light:['#f5f1e9','#fffefa','#806342'],dark:['#080706','#1a1815','#f0d4a9']},{id:'ice',name:'Ice White & Black',note:'Cool white with a sky accent',light:['#edf4f7','#ffffff','#28758d'],dark:['#05090c','#151b1f','#b7edfa']},{id:'mint',name:'Soft Mint & Charcoal',note:'Pale sage background and charcoal',light:['#edf4ef','#ffffff','#35845a'],dark:['#050907','#151a17','#b5f2c9']}];
  const lightLabel=language==='ar'?'فاتح':'Light',nightLabel=language==='ar'?'ليلي':'Night';
  return `<section class="card theme-settings"><div class="theme-settings-head"><div><h3>${language==='ar'?'سمة التطبيق':'App appearance'}</h3><p>${language==='ar'?'اختر سمة واحدة للوضعين الفاتح والليلي.':'Choose one palette for both light and night mode.'}</p></div><span class="theme-mode-chip">${theme==='dark'?nightLabel:lightLabel}</span></div><div class="theme-presets">${options.map(item=>`<button type="button" class="theme-preset" data-palette="${item.id}" aria-pressed="${palette===item.id}"><span class="preset-title">${item.name}</span><span class="preset-note">${item.note}</span><span class="preset-swatches"><span class="preset-swatch-group"><small>${lightLabel}</small><i class="preset-swatch" style="--swatch-bg:${item.light[0]};--swatch-panel:${item.light[1]};--swatch-accent:${item.light[2]}"></i></span><span class="preset-swatch-group"><small>${nightLabel}</small><i class="preset-swatch" style="--swatch-bg:${item.dark[0]};--swatch-panel:${item.dark[1]};--swatch-accent:${item.dark[2]}"></i></span></span><span class="preset-selected">${palette===item.id?(language==='ar'?'محددة':'Selected'):(language==='ar'?'اختيار السمة':'Choose theme')}</span></button>`).join('')}</div></section>`
}
const views={
dashboard:()=>{const scale=db.period==="اليوم"?1/30:db.period==="آخر 7 أيام"?7/30:db.period==="الشهر الماضي"?0.96:1;const totals=db.buildings.reduce((a,b)=>({c:a.c+b.consumption*scale,p:a.p+b.production*scale,pan:a.pan+b.panels}),{c:0,p:0,pan:0});const grid=totals.c-totals.p;const saved=totals.p*db.settings.rate;const carbon=totals.p*db.settings.carbon;return `${heading('صباح الخير 👋','إليك ملخص أداء الطاقة الشمسية في الحرم الجامعي اليوم.',periodSelect())}<div class="kpi-grid">
<div class="card kpi"><div class="kpi-top">إنتاج الطاقة الشمسية <span class="kpi-icon">☼</span></div><div class="kpi-value">${fmt(totals.p)} <small>kWh</small></div><div class="kpi-foot"><span class="positive">↑ 8.4%</span> مقارنة بالفترة السابقة</div><svg class="kpi-spark" viewBox="0 0 70 30"><path d="M2 23 Q12 19 17 22T29 15T41 19T53 8T68 5" fill="none" stroke="#69a77c" stroke-width="2"/></svg></div>
<div class="card kpi"><div class="kpi-top">استهلاك المباني <span class="kpi-icon">▦</span></div><div class="kpi-value">${fmt(totals.c)} <small>kWh</small></div><div class="kpi-foot">إجمالي استهلاك المباني المسجل</div></div>
<div class="card kpi"><div class="kpi-top">التوفير التقديري <span class="kpi-icon">↗</span></div><div class="kpi-value">${fmt(saved)} <small>ج.م</small></div><div class="kpi-foot"><span class="positive">${pct(totals.p,totals.c)}%</span> من قيمة الطاقة المولدة</div></div>
<div class="card kpi"><div class="kpi-top">انبعاثات تم تجنبها <span class="kpi-icon">♧</span></div><div class="kpi-value">${(carbon/1000).toFixed(1)} <small>طن CO₂e</small></div><div class="kpi-foot">بحسب معامل الانبعاثات المحفوظ بالإعدادات</div></div></div>
<div class="grid-main"><section class="card panel"><div class="panel-head"><div><div class="panel-title">الإنتاج والاستهلاك</div><div class="panel-sub">مقارنة الطاقة خلال آخر 7 أيام · kWh</div></div><div class="legend"><span><i></i> شمسي</span><span><i class="legend-grid"></i> استهلاك</span></div></div><div class="chart-box"><canvas id="energyChart"></canvas></div><div class="chart-caption"><span>قراءات تجريبية لأغراض العرض</span><span>آخر تحديث: اليوم 10:45 ص</span></div></section>
<section class="card panel"><div class="panel-head"><div><div class="panel-title">مصادر الطاقة</div><div class="panel-sub">مساهمة الشمس من إجمالي الاستهلاك</div></div><span class="tag-demo">تقديري</span></div><div class="ring-wrap"><div class="ring" id="sourceRing"><div class="ring-center"><b>${pct(totals.p,totals.c)}%</b><small>طاقة شمسية</small></div></div><div class="ring-legend"><div class="ring-item"><span><i class="dot green"></i>الطاقة الشمسية</span><b>${fmt(totals.p)} kWh</b></div><div class="ring-item"><span><i class="dot gray"></i>من الشبكة</span><b>${fmt(grid)} kWh</b></div><div class="ring-item"><span>عدد المباني</span><b>${db.buildings.length}</b></div></div></div></section></div>
<div class="section-row"><h2>أداء المباني</h2><a class="text-link" href="#buildings">عرض كل المباني ←</a></div><div class="building-grid">${db.buildings.map((b,i)=>buildingCard(b,i)).join('')}</div><div class="section-row"><h2>حالة البطاريات</h2><a class="text-link" href="#batteries">تفاصيل البطاريات ←</a></div><section class="card status-card"><div class="battery-list">${db.batteries.slice(0,4).map(batteryRow).join('')}</div></section>`},
buildings:()=>`${heading('المباني','إدارة مباني الجامعة ومتابعة استهلاكها وإنتاجها الشمسي.',`${btnAdd('إضافة مبنى','building')}`)}<div class="toolbar" style="margin-bottom:14px"><input class="field-input search" id="buildingSearch" placeholder="ابحث عن مبنى أو كلية"><span class="tag-demo">${db.buildings.length} مبانٍ تجريبية</span></div><div class="building-grid" id="buildingGrid">${db.buildings.map((b,i)=>buildingCard(b,i,true)).join('')}</div>`,
panels:()=>`${heading('الألواح الشمسية','إدارة الألواح المرتبطة بكل مبنى ومواصفاتها.',`${btnAdd('إضافة ألواح','panel')}`)}<div class="kpi-grid"><div class="card kpi"><div class="kpi-top">إجمالي الألواح <span class="kpi-icon">▧</span></div><div class="kpi-value">${fmt(db.buildings.reduce((s,b)=>s+b.panels,0))} <small>لوح</small></div><div class="kpi-foot">${db.buildings.length} مبانٍ · العدد موحد افتراضيًا</div></div><div class="card kpi"><div class="kpi-top">قدرة اللوح <span class="kpi-icon">ϟ</span></div><div class="kpi-value">${db.settings.panelW} <small>W</small></div><div class="kpi-foot">قيمة تجريبية قابلة للتعديل</div></div><div class="card kpi"><div class="kpi-top">القدرة المركبة <span class="kpi-icon">↗</span></div><div class="kpi-value">${(db.settings.panelW*db.buildings.reduce((s,b)=>s+b.panels,0)/1000).toFixed(1)} <small>kWp</small></div><div class="kpi-foot">مجموع قدرة الألواح الاسمية</div></div><div class="card kpi"><div class="kpi-top">حالة النظام <span class="kpi-icon">✓</span></div><div class="kpi-value" style="font-size:19px">${db.panelStatus}</div><div class="kpi-foot">لا توجد قراءات أجهزة فعلية متصلة</div></div></div><section class="card table-card"><div class="table-wrap"><table><thead><tr><th>المبنى</th><th>عدد الألواح</th><th>قدرة اللوح</th><th>الإنتاج اليومي</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${db.buildings.map(b=>`<tr><td class="table-name">${b.name}<span class="sub-cell">${b.faculties}</span></td><td>${fmt(b.panels)} لوح</td><td>${db.settings.panelW} W</td><td>${fmt(b.production)} kWh</td><td><span class="badge">● ${db.panelStatus}</span></td><td><div class="row-actions"><button data-action="edit-panel" data-id="${b.id}">تعديل</button><button data-action="del-panel" data-id="${b.id}">حذف</button></div></td></tr>`).join('')}</tbody></table></div></section>`,
batteries:()=>{let charge=db.batteries.reduce((s,b)=>s+b.capacity*b.charge/100,0),cap=db.batteries.reduce((s,b)=>s+b.capacity,0),used=db.batteries.reduce((s,b)=>s+b.todayUsed,0);return `${heading('البطاريات','متابعة الشحن والطاقة المخزنة والاستهلاك اليومي.',`${btnAdd('إضافة بطارية','battery')}`)}<div class="kpi-grid"><div class="card kpi"><div class="kpi-top">الشحن الحالي <span class="kpi-icon">▣</span></div><div class="kpi-value">${pct(charge,cap)}<small>%</small></div><div class="kpi-foot">${fmt(charge)} من ${fmt(cap)} kWh سعة كلية</div></div><div class="card kpi"><div class="kpi-top">الطاقة المخزنة <span class="kpi-icon">ϟ</span></div><div class="kpi-value">${fmt(charge)} <small>kWh</small></div><div class="kpi-foot">مجموع الشحن الحالي للمباني</div></div><div class="card kpi"><div class="kpi-top">استهلاك البطاريات اليوم <span class="kpi-icon">↘</span></div><div class="kpi-value">${fmt(used)} <small>kWh</small></div><div class="kpi-foot">استهلاك تجريبي لليوم</div></div><div class="card kpi"><div class="kpi-top">عدد البطاريات <span class="kpi-icon">▤</span></div><div class="kpi-value">${db.batteries.length}</div><div class="kpi-foot">بطارية مرتبطة بمبانٍ</div></div></div><section class="card table-card"><div class="table-wrap"><table><thead><tr><th>البطارية</th><th>المبنى</th><th>السعة</th><th>الشحن</th><th>المستهلك اليوم</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${db.batteries.map(b=>{let building=db.buildings.find(x=>x.id===b.buildingId);return `<tr><td class="table-name">${b.name}</td><td>${building?.name||'غير مرتبطة'}</td><td>${b.capacity} kWh</td><td><div>${b.charge}%</div><div class="mini-progress" style="width:95px"><i style="width:${b.charge}%"></i></div></td><td>${b.todayUsed} kWh</td><td><span class="badge">● ${b.status}</span></td><td><div class="row-actions"><button data-action="edit-battery" data-id="${b.id}">تعديل</button><button data-action="del-battery" data-id="${b.id}">حذف</button></div></td></tr>`}).join('')}</tbody></table></div></section><div class="notice">بيانات الشحن والتفريغ في هذه النسخة تجريبية. توصيل قراءات فعلية يتطلب ربط النظام بمصدر البطاريات أو إدخالها يدويًا.</div>`},
weather:()=>`${heading('الطقس والتوقعات','توقع إنتاج الألواح بحسب حالة الطقس. القيم تقديرية للعرض.',`<select class="select" id="weatherCondition"><option value="sunny">مشمس</option><option value="mixed">غائم</option><option value="cloudy">غائم</option><option value="rainy">ممطر</option><option value="dusty">أتربة</option></select>`)}<div class="card weather-banner"><div class="sun" id="weatherIcon">☀</div><div><h3 id="weatherTitle">غدًا · مشمس</h3><p>توقع تجريبي للحرم الجامعي · يتغير الإنتاج حسب الظروف الفعلية</p></div><div class="forecast-output" id="forecastTotal"></div></div><div class="kpi-grid"><div class="card kpi"><div class="kpi-top">إنتاج متوقع غدًا <span class="kpi-icon">☼</span></div><div class="kpi-value" id="weatherKpi">—</div><div class="kpi-foot">مجموع إنتاج الألواح في الجامعة</div></div><div class="card kpi"><div class="kpi-top">عامل الطقس <span class="kpi-icon">◉</span></div><div class="kpi-value" id="weatherFactor">—</div><div class="kpi-foot">نسبة افتراضية من يوم مشمس</div></div><div class="card kpi"><div class="kpi-top">عدد الألواح <span class="kpi-icon">▧</span></div><div class="kpi-value">${fmt(db.buildings.reduce((s,b)=>s+b.panels,0))}</div><div class="kpi-foot">موزعة بالتساوي حسب الإعدادات</div></div><div class="card kpi"><div class="kpi-top">التوفير المتوقع <span class="kpi-icon">↗</span></div><div class="kpi-value" id="weatherSaving">—</div><div class="kpi-foot">تقدير باستخدام تعريفة الإعدادات</div></div></div><div class="section-row"><h2>توقعات الأيام القادمة</h2><span class="tag-demo">بيانات طقس تجريبية</span></div><div class="forecast-strip">${[['اليوم','☀','مشمس','1,713'],['غدًا','⛅','غائم','1,456'],['الأربعاء','☁','غائم','1,028'],['الخميس','☂','ممطر','514'],['الجمعة','◌','أتربة','857']].map((d,i)=>`<div class="forecast-day ${i===0?'today':''}"><small>${d[0]}</small><div class="weather-icon">${d[1]}</div><b>${d[2]}</b><em>${d[3]} kWh</em></div>`).join('')}</div><div class="section-row"><h2>الإنتاج المتوقع حسب المبنى</h2></div><section class="card table-card"><div class="table-wrap"><table><thead><tr><th>المبنى</th><th>عدد الألواح</th><th>إنتاج يوم مشمس</th><th>المتوقع للحالة</th><th>التوفير المتوقع</th></tr></thead><tbody id="weatherRows"></tbody></table></div></section>`,
reports:()=>`${heading('التقارير','ملخصات الإنتاج والاستهلاك والتوفير لكل مبنى.',`<select class="select" id="reportPeriod"><option>هذا الشهر</option><option>الشهر الماضي</option><option>هذا العام</option></select><button class="btn btn-plain" id="exportBtn">↓ تنزيل CSV</button>`)}<div class="report-summary" id="reportSummary"></div><section class="card panel" style="margin-bottom:15px"><div class="panel-head"><div><div class="panel-title">الإنتاج والاستهلاك الشهري</div><div class="panel-sub">مقارنة تجريبية حسب المبنى</div></div><div class="legend"><span><i></i> شمسي</span><span><i class="legend-grid"></i> استهلاك</span></div></div><div class="chart-box"><canvas id="reportChart"></canvas></div></section><section class="card table-card"><div class="table-wrap"><table><thead><tr><th>المبنى</th><th>الاستهلاك</th><th>إنتاج شمسي</th><th>من الشبكة</th><th>توفير تقديري</th><th>خفض الكربون</th></tr></thead><tbody>${db.buildings.map(b=>`<tr><td class="table-name">${b.name}</td><td>${fmt(b.consumption)} kWh</td><td>${fmt(b.production)} kWh</td><td>${fmt(Math.max(0,b.consumption-b.production))} kWh</td><td>${money(b.production*db.settings.rate)}</td><td>${(b.production*db.settings.carbon/1000).toFixed(2)} طن</td></tr>`).join('')}</tbody></table></div></section><div class="notice">التقرير تجريبي ويستخدم استهلاكات مولدة للتوضيح. يجب مراجعة الفواتير الفعلية والتعريفة المناسبة للجامعة قبل اعتماد أرقام مالية.</div>`,
settings:()=>`${heading('الإعدادات','إعدادات التعريفة ومواصفات النظام التجريبي.')}${paletteSettingsMarkup()}<div class="settings-grid"><section class="card settings-card"><h3>إعدادات الطاقة الشمسية</h3><p>تُستخدم هذه القيم لتقدير القدرة والإنتاج في صفحات المشروع.</p><div class="form-row"><div class="field"><label>قدرة اللوح (واط)</label><input id="setPanelW" class="field-input" type="number" min="1" value="${db.settings.panelW}"></div><div class="field"><label>عدد الألواح لكل مبنى</label><input id="setPanelCount" class="field-input" type="number" min="1" value="${db.settings.panelsPerBuilding}"></div></div><div class="field"><label>معامل خفض انبعاثات الكهرباء (كجم CO₂e لكل kWh)</label><input id="setCarbon" class="field-input" type="number" step="0.001" value="${db.settings.carbon}"></div><div class="notice">المعامل افتراضي قابل للتغيير، ويجب توثيق قيمته وسنة مرجعه عند استخدامه في تقرير رسمي.</div></section><section class="card settings-card"><h3>تعريفة الكهرباء الافتراضية</h3><p>اختر قيمة قابلة للتعديل؛ فئة تعاقد الجامعة قد تختلف عن التعريفة التجارية المعتادة.</p><div class="field"><label>سعر مرجعي لكل kWh (جنيه)</label><input id="setRate" class="field-input" type="number" min="0" step="0.01" value="${db.settings.rate}"></div><div class="notice">التعريفة المختارة تستخدم كتقدير مبسط للتوفير، وليست حساب فاتورة رسميًا متعدد البنود.</div></section><section class="card settings-card"><h3>شرائح التعريفة التجارية المرجعية</h3><p>قيم مرجعية قابلة للمراجعة والتحديث من مصادر التعريفة.</p><div class="table-wrap"><table class="settings-table"><thead><tr><th>الاستهلاك الشهري</th><th>سعر مرجعي ج.م/kWh</th></tr></thead><tbody><tr><td>0–100 kWh</td><td>1.00</td></tr><tr><td>101–250 kWh</td><td>2.00</td></tr><tr><td>251–600 kWh</td><td>2.64</td></tr><tr><td>601–1000 kWh</td><td>2.72</td></tr><tr><td>أكثر من 1000 kWh</td><td>2.79</td></tr></tbody></table></div><div class="notice">تعريفة توضيحية للواجهة، وتحتاج إلى تأكيد فئة تعاقد الجامعة والتحديث الرسمي قبل اعتمادها.</div></section><section class="card settings-card"><h3>البيانات التجريبية</h3><p>تغييرات المباني والبطاريات تُحفظ في هذا المتصفح فقط.</p><div class="tag-demo">وضع تجريبي · لا يوجد تسجيل دخول</div><div style="margin-top:18px"><button class="btn btn-danger" id="resetData">استعادة البيانات الافتراضية</button></div><div class="notice">لا يوجد حتى الآن خادم أو قاعدة بيانات مركزية. تنظيف بيانات المتصفح قد يمسح التعديلات المحفوظة.</div></section></div>`
};
function buildingCard(b,i,actions=false){let saving=pct(b.production,b.consumption);return `<article class="card building-card"><div class="building-top"><div class="building-glyph">${iconFor(i)}</div><div><div class="building-name">${b.name}</div><div class="building-type">${b.faculties}</div></div>${actions?`<button class="building-more" data-action="edit-building" data-id="${b.id}" title="تعديل">⋯</button>`:''}</div><div class="building-values"><div><small>الاستهلاك</small><b>${fmt(b.consumption)} kWh</b></div><div><small>إنتاج شمسي</small><b>${fmt(b.production)} kWh</b></div><div><small>الألواح</small><b>${b.panels} لوح</b></div></div><div class="progress-line"><span style="width:${Math.min(100,saving)}%"></span></div><div style="display:flex;justify-content:space-between;font-size:9px;color:#91a096;margin-top:6px"><span>تغطية الطاقة الشمسية</span><b style="color:#50815d">${saving}%</b></div>${actions?`<div class="row-actions" style="margin-top:11px"><button data-action="edit-building" data-id="${b.id}">تعديل</button><button data-action="del-building" data-id="${b.id}">حذف</button></div>`:''}</article>`}
function batteryRow(b){let building=db.buildings.find(x=>x.id===b.buildingId);return `<div class="battery-row"><div class="battery-icon">▣</div><div><b>${building?.name||b.name}</b><small>${b.name} · ${b.capacity} kWh سعة</small><div class="mini-progress"><i style="width:${b.charge}%"></i></div></div><div class="battery-level">${b.charge}%</div></div>`}
function bindCommon(){document.querySelectorAll('.theme-preset').forEach(button=>button.addEventListener('click',()=>setPalette(button.dataset.palette)));document.querySelector('#menuToggle').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');document.querySelectorAll('.nav-link[data-page]').forEach(a=>a.onclick=()=>document.querySelector('#sidebar').classList.remove('open'));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b.dataset.id));document.querySelector('#periodSelect')?.addEventListener('change',e=>{db.period=arabicPeriod(e.target.value);saveDB();render();toast('تم تحديث الفترة المعروضة')});document.querySelector('#weatherCondition')?.addEventListener('change',updateWeather);document.querySelector('#forecastPanelCount')?.addEventListener('input',updateWeather);const rp=document.querySelector('#reportPeriod');if(rp){rp.value=language==='en'?translateMarkup(db.reportPeriod||'هذا الشهر'):(db.reportPeriod||'هذا الشهر');rp.onchange=()=>{db.reportPeriod=arabicPeriod(rp.value);saveDB();drawReport()}}document.querySelector('#buildingSearch')?.addEventListener('input',e=>{const q=e.target.value.trim();document.querySelector('#buildingGrid').innerHTML=db.buildings.filter(b=>(b.name+b.faculties).includes(q)).map((b,i)=>buildingCard(b,i,true)).join('')||'<div class="empty-state">لا توجد مبانٍ مطابقة</div>';document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b.dataset.id))});document.querySelector('#weatherCondition')&&updateWeather();document.querySelector('#exportBtn')?.addEventListener('click',exportCsv);document.querySelector('#resetData')?.addEventListener('click',()=>{if(confirm('استعادة البيانات الافتراضية ومسح التعديلات الحالية؟')){db=structuredClone(seed);saveDB();render();toast('تمت استعادة البيانات الافتراضية')}});document.querySelector('#setRate')?.addEventListener('change',saveSettings);document.querySelector('#setCarbon')?.addEventListener('change',saveSettings);document.querySelector('#setPanelW')?.addEventListener('change',saveSettings);document.querySelector('#setPanelCount')?.addEventListener('change',saveSettings)}
function saveSettings(){db.settings.rate=+document.querySelector('#setRate').value||0;db.settings.carbon=+document.querySelector('#setCarbon').value||0;db.settings.panelW=+document.querySelector('#setPanelW').value||1;db.settings.panelsPerBuilding=+document.querySelector('#setPanelCount').value||1;db.buildings.forEach(b=>b.panels=db.settings.panelsPerBuilding);saveDB();toast('تم حفظ الإعدادات');}
function handleAction(action,id){if(action.startsWith('add-'))return openForm(action.slice(4));if(action==='edit-building')return openForm('building',id);if(action==='edit-panel')return openForm('panel',id);if(action==='edit-battery')return openForm('battery',id);if(action.startsWith('del-')){const type=action.slice(4);if(!confirm('هل تريد حذف هذا العنصر؟'))return;if(type==='building'){db.buildings=db.buildings.filter(x=>x.id!==id);db.batteries=db.batteries.filter(x=>x.buildingId!==id)}else if(type==='battery')db.batteries=db.batteries.filter(x=>x.id!==id);else if(type==='panel'){const b=db.buildings.find(x=>x.id===id);if(b)b.panels=0}saveDB();render();toast('تم الحذف');}}
function openForm(type,id){let existing;if(id){existing=type==='battery'?db.batteries.find(x=>x.id===id):db.buildings.find(x=>x.id===id)}const buildingOpts=db.buildings.map(b=>`<option value="${b.id}" ${(type==='panel'?existing?.id===b.id:existing?.buildingId===b.id)?'selected':''}>${b.name}</option>`).join('');let title=({building:existing?'تعديل مبنى':'إضافة مبنى',panel:existing?'تعديل الألواح':'إضافة ألواح',battery:existing?'تعديل بطارية':'إضافة بطارية'})[type];let fields='';if(type==='building')fields=`<div class="field wide"><label>اسم المبنى</label><input name="name" class="field-input" required value="${existing?.name||''}" placeholder="مثال: مبنى الصيدلة"></div><div class="field wide"><label>الكليات</label><input name="faculties" class="field-input" value="${existing?.faculties||''}" placeholder="أسماء الكليات داخل المبنى"></div><div class="field"><label>الاستهلاك الشهري (kWh)</label><input name="consumption" class="field-input" type="number" min="0" value="${existing?.consumption||0}"></div><div class="field"><label>الإنتاج الشمسي (kWh)</label><input name="production" class="field-input" type="number" min="0" value="${existing?.production||0}"></div><div class="field"><label>عدد الألواح</label><input name="panels" class="field-input" type="number" min="0" value="${existing?.panels??db.settings.panelsPerBuilding}"></div>`;if(type==='panel')fields=`<div class="field wide"><label>المبنى</label><select name="buildingId" class="field-input">${buildingOpts}</select></div><div class="field"><label>عدد الألواح</label><input name="panels" class="field-input" type="number" min="0" value="${existing?.panels??db.settings.panelsPerBuilding}"></div><div class="field"><label>قدرة اللوح (W)</label><input name="panelW" class="field-input" type="number" value="${db.settings.panelW}"></div><div class="field wide"><label>الإنتاج اليومي التقديري (kWh)</label><input name="production" class="field-input" type="number" value="${existing?.production||0}"></div>`;if(type==='battery')fields=`<div class="field wide"><label>اسم البطارية</label><input name="name" class="field-input" required value="${existing?.name||''}" placeholder="بطارية المبنى"></div><div class="field wide"><label>المبنى</label><select name="buildingId" class="field-input">${buildingOpts}</select></div><div class="field"><label>السعة (kWh)</label><input name="capacity" class="field-input" type="number" min="1" value="${existing?.capacity||120}"></div><div class="field"><label>مستوى الشحن (%)</label><input name="charge" class="field-input" type="number" min="0" max="100" value="${existing?.charge??75}"></div><div class="field wide"><label>استهلاك اليوم (kWh)</label><input name="todayUsed" class="field-input" type="number" min="0" value="${existing?.todayUsed||0}"></div>`;document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><form class="modal" id="itemForm"><div class="modal-head"><h3>${title}</h3><button type="button" class="modal-close" data-close>×</button></div><div class="modal-fields">${fields}</div><div class="modal-actions"><button class="btn btn-primary" type="submit">حفظ البيانات</button><button class="btn btn-plain" type="button" data-close>إلغاء</button></div></form></div>`;document.querySelector('#modalRoot').innerHTML=translateMarkup(document.querySelector('#modalRoot').innerHTML);document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);document.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};document.querySelector('#itemForm').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(type==='building'){let b={id:existing?.id||`b${Date.now()}`,name:d.name,faculties:d.faculties,consumption:+d.consumption,production:+d.production,panels:+d.panels};if(existing)Object.assign(existing,b);else db.buildings.push(b)}if(type==='panel'){let b=db.buildings.find(x=>x.id===d.buildingId);if(b){b.panels=+d.panels;b.production=+d.production;db.settings.panelW=+d.panelW}}if(type==='battery'){let b={id:existing?.id||`bt${Date.now()}`,name:d.name,buildingId:d.buildingId,capacity:+d.capacity,charge:+d.charge,todayUsed:+d.todayUsed,status:'تعمل'};if(existing)Object.assign(existing,b);else db.batteries.push(b)}saveDB();closeModal();render();toast('تم حفظ البيانات بنجاح')}}
function closeModal(){document.querySelector('#modalRoot').innerHTML=''}
function updateWeather(){const keys=["sunny","cloudy","rainy","dusty"],key=keys[(new Date().getDate()+1)%4];const configs={sunny:["مشمس","Sunny","☀",1],cloudy:["غائم","Cloudy","☁",.6],rainy:["ممطر","Rainy","☂",.3],dusty:["أتربة","Dusty","◌",.5]};const [ar,en,icon,factor]=configs[key],label=language==="ar"?ar:en,totalPanels=db.buildings.reduce((s,b)=>s+b.panels,0),perPanel=totalPanels?db.buildings.reduce((s,b)=>s+b.production,0)/(30*totalPanels):2.04,siteOutput=Math.round(totalPanels*perPanel*factor),count=Math.max(1,+document.querySelector("#forecastPanelCount")?.value||10),singleOutput=count*perPanel*factor;const iconEl=document.querySelector("#weatherIcon");if(!iconEl)return;document.querySelector("#weatherTitle").textContent=(language==="ar"?"غدًا · ":"Tomorrow · ")+label;iconEl.textContent=icon;document.querySelector("#forecastTotal").textContent=`${count} ${language==="ar"?"لوح":"panels"} · ${singleOutput.toFixed(1)} kWh`;document.querySelector("#weatherKpi").innerHTML=`${fmt(siteOutput)} <small>kWh</small>`;document.querySelector("#weatherFactor").textContent=`${Math.round(factor*100)}%`;document.querySelector("#weatherSaving").innerHTML=`${fmt(siteOutput*db.settings.rate)} <small>${language==="ar"?"ج.م":"EGP"}</small>`;document.querySelector("#weatherRows").innerHTML=translateMarkup(db.buildings.map(b=>{const daily=b.panels*perPanel;return `<tr><td class="table-name">${b.name}</td><td>${fmt(b.panels)}</td><td>${daily.toFixed(1)} kWh</td><td>${(daily*factor).toFixed(1)} kWh</td><td>${money(daily*factor*db.settings.rate)}</td></tr>`}).join(""));}
function drawDashboard(){const totalP=db.buildings.reduce((s,b)=>s+b.production,0),totalC=db.buildings.reduce((s,b)=>s+b.consumption,0),solarPct=pct(totalP,totalC),dark=document.body.classList.contains('dark-theme'),chartTheme=getComputedStyle(document.body),ringSolar=chartTheme.getPropertyValue('--chart-solar').trim()||(dark?'#c8ff57':'#35b975'),ringTrack=chartTheme.getPropertyValue('--chart-track').trim()||(dark?'#25302b':'#e6efe8');const ring=document.querySelector("#sourceRing");if(ring)ring.style.background=`conic-gradient(${ringSolar} 0deg ${solarPct*3.6}deg,${ringTrack} ${solarPct*3.6}deg 360deg)`;const labels=db.buildings.map(b=>translateMarkup(b.faculties.split(" · ")[0]));const factor=0.985+Math.sin(Date.now()/45000)*0.025;drawBarChart("energyChart",labels,db.buildings.map(b=>Math.round(b.production/30*factor)),db.buildings.map(b=>Math.round(b.consumption/30*factor)));const sub=document.querySelector(".grid-main .panel-sub");if(sub)sub.textContent=language==="ar"?"استهلاك وإنتاج اليوم حسب الكلية · kWh":"Daily energy by faculty · kWh";const updated=document.querySelector(".grid-main .chart-caption span:last-child");if(updated)updated.textContent=(language==="ar"?"تحديث تجريبي: ":"Demo refresh: ")+new Intl.DateTimeFormat(language==="ar"?"ar-EG":"en-US",{hour:"numeric",minute:"2-digit"}).format(new Date());}
function drawReport(){const period=arabicPeriod(document.querySelector("#reportPeriod")?.value||db.reportPeriod||"هذا الشهر"),scale=period==="اليوم"?1/30:period==="آخر 7 أيام"?7/30:period==="الشهر الماضي"?0.96:period==="هذا العام"?12:1,totalC=db.buildings.reduce((s,b)=>s+b.consumption*scale,0),totalP=db.buildings.reduce((s,b)=>s+b.production*scale,0);document.querySelector("#reportSummary").innerHTML=`<div class="card report-tile"><small>${language==="ar"?"إجمالي الاستهلاك":"Total consumption"}</small><b>${fmt(totalC)} kWh</b></div><div class="card report-tile"><small>${language==="ar"?"إجمالي الإنتاج الشمسي":"Total solar generation"}</small><b>${fmt(totalP)} kWh</b></div><div class="card report-tile"><small>${language==="ar"?"التوفير المالي التقديري":"Estimated savings"}</small><b>${money(totalP*db.settings.rate)}</b></div>`;drawBarChart("reportChart",db.buildings.map((_,i)=>`${language==="ar"?"مبنى":"Bldg"} ${i+1}`),db.buildings.map(x=>x.production*scale),db.buildings.map(x=>x.consumption*scale));const body=document.querySelector(".table-card tbody");if(body)body.innerHTML=translateMarkup(db.buildings.map(b=>`<tr><td class="table-name">${b.name}</td><td>${fmt(b.consumption*scale)} kWh</td><td>${fmt(b.production*scale)} kWh</td><td>${fmt(Math.max(0,b.consumption-b.production)*scale)} kWh</td><td>${money(b.production*scale*db.settings.rate)}</td><td>${(b.production*scale*db.settings.carbon/1000).toFixed(2)} ${language==="ar"?"طن":"tons"}</td></tr>`).join(""));}
function drawBarChart(id,labels,a,b){
  const canvas=document.getElementById(id);if(!canvas)return;
  const box=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=box.width*dpr;canvas.height=box.height*dpr;
  const c=canvas.getContext('2d'),dark=document.body.classList.contains('dark-theme'),paletteStyle=getComputedStyle(document.body),chartSolar=paletteStyle.getPropertyValue('--chart-solar').trim()||(dark?'#48cf63':'#168b58'),chartSolarTop=paletteStyle.getPropertyValue('--chart-solar-top').trim()||(dark?'#ddff74':'#38cf8a'),chartConsumption=paletteStyle.getPropertyValue('--chart-consumption').trim()||(dark?'#2879d7':'#397e9d'),chartConsumptionTop=paletteStyle.getPropertyValue('--chart-consumption-top').trim()||(dark?'#75e8ff':'#78c5df'),chartGrid=paletteStyle.getPropertyValue('--chart-grid').trim()||(dark?'#343c5b':'#e7eee9'),chartText=paletteStyle.getPropertyValue('--chart-text').trim()||(dark?'#b5bed8':'#778a7e'),w=box.width,h=box.height,pad={t:16,r:20,b:42,l:42},iw=w-pad.l-pad.r,ih=h-pad.t-pad.b,max=Math.max(1,...a,...b)*1.15,group=iw/labels.length,bw=Math.min(34,group*.24);
  const draw=progress=>{c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);c.font='10px IBM Plex Sans Arabic, sans-serif';c.textAlign='right';
    for(let i=0;i<4;i++){const y=pad.t+ih*i/3,value=max*(1-i/3);c.strokeStyle=chartGrid;c.lineWidth=1;c.beginPath();c.moveTo(pad.l,y);c.lineTo(w-pad.r,y);c.stroke();c.fillStyle=chartText;c.fillText(max>=1000?(value/1000).toFixed(1)+'k':Math.round(value).toString(),pad.l-8,y+3)}
    labels.forEach((lab,i)=>{const x=pad.l+group*i+group/2,ha=ih*a[i]/max*progress,hb=ih*b[i]/max*progress;let grad=c.createLinearGradient(0,pad.t+ih-ha,0,pad.t+ih);grad.addColorStop(0,chartSolarTop);grad.addColorStop(1,chartSolar);c.fillStyle=grad;c.shadowColor=chartSolar;c.shadowBlur=12;rounded(c,x-bw-3,pad.t+ih-ha,bw,ha,5);c.fill();c.shadowBlur=0;let blue=c.createLinearGradient(0,pad.t+ih-hb,0,pad.t+ih);blue.addColorStop(0,chartConsumptionTop);blue.addColorStop(1,chartConsumption);c.fillStyle=blue;c.shadowColor=chartConsumption;c.shadowBlur=10;rounded(c,x+3,pad.t+ih-hb,bw,hb,5);c.fill();c.shadowBlur=0;c.fillStyle=chartText;c.textAlign='center';c.fillText(lab,x,h-9,group-4)})
  };
  const start=performance.now(),animate=now=>{const t=Math.min(1,(now-start)/750),ease=1-Math.pow(1-t,3);draw(ease);if(t<1)requestAnimationFrame(animate)};requestAnimationFrame(animate);
}
function rounded(c,x,y,w,h,r){if(h<0)return;c.beginPath();c.roundRect(x,y,w,h,[Math.min(r,w/2,h/2),Math.min(r,w/2,h/2),0,0]);c.closePath()}
function exportCsv(){let rows=[['المبنى','الاستهلاك kWh','إنتاج شمسي kWh','من الشبكة kWh','توفير تقديري جنيه','خفض الكربون طن'],...db.buildings.map(b=>[b.name,b.consumption,b.production,b.consumption-b.production,(b.production*db.settings.rate).toFixed(2),(b.production*db.settings.carbon/1000).toFixed(2)])];const csv='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='siraj-energy-report.csv';a.click();URL.revokeObjectURL(a.href);toast('تم تنزيل التقرير')}
window.addEventListener('hashchange',render);window.addEventListener('resize',()=>{if(location.hash==='#dashboard'||!location.hash)drawDashboard();if(location.hash==='#reports')drawReport()});render();setInterval(()=>{if((location.hash.slice(1)||"dashboard")==="dashboard")drawDashboard()},45000);
